#include <vector>
#include <cstddef>
#include <omp.h>

int edgeCount(std::vector<int> const& A, size_t N) {
    const size_t NN = N * N;
    if (N == 0 || A.size() < NN) return 0;

    long long total = 0;

    #pragma omp parallel for reduction(+:total) schedule(static)
    for (std::ptrdiff_t idx = 0; idx < static_cast<std::ptrdiff_t>(NN); ++idx) {
        total += (A[static_cast<size_t>(idx)] != 0) ? 1 : 0;
    }

    return static_cast<int>(total);
}
